def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """Check if in given list of numbers, are any two numbers closer to each other than
    given threshold.
    >>> has_close_elements([1.0, 2.0, 3.0], 0.5)
    False
    >>> has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    True
    """
from typing import List


def has_close_elements(numbers: List[float], threshold: float) -> bool:
    for idx, elem in enumerate(numbers):
        for idx2, elem2 in enumerate(numbers):
            if idx != idx2:
                distance = abs(elem - elem2)
                if distance < threshold:
                    return True

    return False

tests:
void main() {
  final candidate = hasCloseElements;


  expect(candidate([1.0, 2.0, 3.9, 4.0, 5.0, 2.2], 0.05), false);
  expect(candidate([1.0, 2.0, 5.9, 4.0, 5.0], 0.95), true);


  expect(candidate([1.1, 2.2, 3.1, 4.1, 5.1], 1.0), true);
  expect(candidate([1.1, 2.2, 3.1, 4.1, 5.1], 0.5), false);
}

void expect(dynamic a, dynamic b) {
