bool isPalindrome(String string) {
  return string == string.split('').reversed.join('');
}

@pragma('vm:entry-point')
String makePalindrome(String stringArg0) {
  if (stringArg0.isEmpty) {
    return '';
  }

  int beginningOfSuffix = 0;

  while (!isPalindrome(stringArg0.substring(beginningOfSuffix))) {
    beginningOfSuffix++;
  }

  return stringArg0 + stringArg0.substring(0, beginningOfSuffix).split('').reversed.join('');
}

