List<double> rescaleToUnit(List<double> numbers) {
  double minNumber = numbers.reduce((a, b) => a < b ? a : b);
  double maxNumber = numbers.reduce((a, b) => a > b ? a : b);
  return numbers.map((x) => (x - minNumber) / (maxNumber - minNumber)).toList();
}

