int specialFilter(List<int> nums) {
  int count = 0;
  List<int> oddDigits = [1, 3, 5, 7, 9];

  for (int num in nums) {
    if (num > 10) {
      String numberAsString = num.toString();
      int firstDigit = int.parse(numberAsString[0]);
      int lastDigit = int.parse(numberAsString[numberAsString.length - 1]);

      if (oddDigits.contains(firstDigit) && oddDigits.contains(lastDigit)) {
        count++;
      }
    }
  }

  return count;
}

